+        'target_kind',
+        'queue',
+        'trigger_type',
+        'mode',
+        'status',
+        'source_diagnosis_event_ref',
+      ],
+      relation_to_question_and_evidence:
+        'ReviewTask is created only for typed blockers or low-confidence candidates; it preserves blocker-specific source refs.',
+      privacy_boundary:
+        'ReviewTask candidates route evidence blockers and do not include learner response payloads.',
+      immutability_rule: 'Completion requires evidence; a candidate route is not a completed human review.',
+    },
