+      cardinality: 'one_attempt_reads_question_level_projection_bundle',
+      stable_id_rule: 'edge:attempt_reads_kg_evidence:<attempt_id>:<question_key>:<kg_projection_hash>',
+      fail_closed_semantics:
+        'If KG evidence posture is missing, log Attempt but suppress diagnosis wording and route the missing posture.',
+    },
+    {
+      edge_family: 'attempt_targets_question',
+      from_node: 'Attempt',
+      to_node: 'Question',
+      cardinality: 'many_to_one_when_question_ref_present',
+      stable_id_rule: 'edge:attempt_targets_question:<attempt_id>:<question_key>',
+      fail_closed_semantics:
+        'Questionless sessions remain valid; questionless attempts cannot generate question-level diagnosis events.',
+    },
+    {
+      edge_family: 'diagnosis_event_may_create_review_task',
+      from_node: 'DiagnosisEvent',
+      to_node: 'ReviewTask',
+      cardinality: 'zero_or_many',
+      stable_id_rule: 'edge:diagnosis_event_may_create_review_task:<diagnosis_event_id>:<review_task_candidate_key>',
+      fail_closed_semantics:
+        'Only blocker-specific or candidate-specific event postures create ReviewTask candidates.',
+    },
+    {
+      edge_family: 'diagnosis_event_uses_evidence_posture',
+      from_node: 'DiagnosisEvent',
+      to_node: 'EvidencePosture',
+      cardinality: 'exactly_one_question_level_projection_bundle',
+      stable_id_rule: 'edge:diagnosis_event_uses_evidence_posture:<diagnosis_event_id>:<question_key>',
+      fail_closed_semantics:
+        'Generated wording strength cannot exceed method, visual, rights, and source/render evidence posture.',
+    },
+    {
+      edge_family: 'review_task_routes_blocker',
+      from_node: 'ReviewTask',
+      to_node: 'Question, MethodMap, ProcedureModel, SourceFigureAsset, RightsDisplayPolicy, QuestionRenderModel',
+      cardinality: 'one_review_candidate_per_blocker_type_per_question',
+      stable_id_rule: 'edge:review_task_routes_blocker:<review_task_candidate_key>:<target_ref>',
+      fail_closed_semantics:
+        'Unresolved blockers remain explicit ReviewTask candidates; they are not downgraded into vague low confidence.',
