+
+function blockerTypesForProjection({ availability = {}, visual = {}, display = {}, diagnostic = {}, review = {}, sourceRender = {} }) {
+  const blockers = [];
+  if (missingVisual({ availability, visual, diagnostic })) blockers.push('missing_visual_evidence');
+  if (rightsBlocked({ display, review })) blockers.push('rights_display_blocker');
+  if (methodBlocked(diagnostic)) blockers.push('method_evidence_blocked');
+  if (lowOrCandidateConfidence({ availability, diagnostic })) blockers.push('low_confidence_method_candidate');
+  if (sourceRenderInconsistent(sourceRender)) blockers.push('source_render_inconsistency');
+  return uniqueSorted(blockers);
+}
+
+function ruleByPosture(methodDiagnosticPosture) {
+  const rules = new Map(diagnosticPostureRules().map((rule) => [rule.method_diagnostic_posture, rule]));
+  return rules.get(methodDiagnosticPosture) ?? rules.get('routing_logging_review_queue_only');
+}
+
+function classifyDiagnosis({ availability = {}, visual = {}, diagnostic = {}, blockers = [] }) {
+  if (blockers.includes('missing_visual_evidence')) {
+    return {
+      event_type: 'diagnosis.visual_dependent_suppressed',
+      wording_strength: 'none',
+      student_wording_allowed: false,
+      event_posture: 'visual_dependent_suppression',
+      reason_code: 'visual_not_ready',
+    };
+  }
+  if (blockers.includes('method_evidence_blocked')) {
+    return {
+      event_type: 'diagnosis.suppressed',
+      wording_strength: 'none',
+      student_wording_allowed: false,
+      event_posture: 'method_diagnosis_suppressed',
+      reason_code: 'method_evidence_blocked',
+    };
+  }
+  if (blockers.includes('source_render_inconsistency')) {
+    return {
+      event_type: 'diagnosis.suppressed',
+      wording_strength: 'none',
+      student_wording_allowed: false,
+      event_posture: 'source_render_inconsistency_suppression',
+      reason_code: 'source_render_inconsistency',
+    };
+  }
+  if (blockers.includes('low_confidence_method_candidate')) {
+    return {
+      event_type: 'diagnosis.candidate_guidance',
+      wording_strength: 'hedged_candidate',
+      student_wording_allowed: true,
+      event_posture: 'candidate_guidance_only',
+      reason_code: 'low_confidence_method_candidate',
+    };
+  }
+
+  const posture = diagnostic.method_diagnostic_posture || visual.method_diagnostic_posture || 'routing_logging_review_queue_only';
+  const rule = ruleByPosture(posture);
+  return {
+    event_type: rule.event_type,
+    wording_strength: rule.wording_strength,
+    student_wording_allowed: rule.student_wording_allowed,
+    event_posture: posture,
+    reason_code: diagnostic.evidence_reason || availability.question_availability || 'kg_evidence_posture',
+  };
+}
+
+function reviewCandidates(questionKey, blockers, routes = reviewRoutingRules()) {
+  const routeMap = new Map(routes.map((route) => [route.blocker_type, route]));
+  return blockers
+    .map((blockerType) => {
+      const route = routeMap.get(blockerType);
+      if (!route) return null;
+      return {
+        review_task_candidate_key: `review_task_candidate:${blockerType}:${questionKey}`,
+        blocker_type: blockerType,
+        queue: route.queue,
+        target_kind: route.target_kind,
+        trigger_type: route.trigger_type,
+        mode: route.review_task_mode,
+        priority: route.priority,
+        status: 'open_candidate_not_materialized',
+      };
+    })
+    .filter(Boolean)
+    .sort((left, right) => compareNatural(left.blocker_type, right.blocker_type));
+}
