+  return {
+    question_key: questionKey,
+    question_ref: questionRef,
+    question_availability: availability.question_availability ?? attempt.question_availability ?? null,
+    attempt_contract: {
+      can_log_attempt: canLogAttempt,
+      attempt_target_ref: { kind: 'question', question_key: questionKey, question_ref: questionRef },
+      kg_query_source: 'kg-v1-query-surfaces.attempt_loop_target_mapping',
+      question_availability_blocked_by_method_confidence:
+        availability.method_confidence_blocks_availability === true,
+      immutable_snapshot_required: true,
